const schema = [{"@context":"https://schema.org","@type":"Service","name":"Health economics &amp; outcomes research","serviceType":"Market access service","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/data-analytics-machine-learning/health-economics-outcome-research/","description":"Cost-effectiveness and budget impact models, real-world evidence, patient-reported outcomes and HTA dossiers.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Why does HEOR matter for a pharmaceutical or device company?","acceptedAnswer":{"@type":"Answer","text":"Because clinical approval and market access are separate decisions made by different people against different evidence. A regulator asks whether the product works and is safe; a payer asks whether it is worth funding at the price you are asking.\n\nHEOR produces the evidence for the second question, and it is the one that decides whether anybody actually receives the treatment."}},{"@type":"Question","name":"Who uses these services?","acceptedAnswer":{"@type":"Answer","text":"Pharmaceutical and biotechnology companies, medical device manufacturers, payers and insurers, policy makers and regulators, academic researchers, providers, CROs and public health bodies.\n\nThe outputs differ considerably between them. A payer-facing budget impact model and an academic cost-utility paper are built from the same evidence and read nothing alike."}},{"@type":"Question","name":"What kinds of study does HEOR cover?","acceptedAnswer":{"@type":"Answer","text":"Cost-effectiveness analysis, budget impact analysis, cost-utility analysis, real-world evidence studies, patient-reported outcomes, systematic reviews and meta-analyses, and HTA submissions.\n\nMost programmes need several of these and in a particular order — the evidence synthesis usually has to exist before the model can be populated."}},{"@type":"Question","name":"How does HEOR support market access and pricing?","acceptedAnswer":{"@type":"Answer","text":"By producing an economic case a payer can examine: what the treatment costs, what it displaces, what it delivers, and how confident anyone can be in those figures.\n\nThe negotiation itself is yours. What we can do is make sure the evidence you take into it holds up when somebody tries to take it apart."}},{"@type":"Question","name":"Can the results be published as well as submitted?","acceptedAnswer":{"@type":"Answer","text":"Yes, and they should be. HEOR studies are published in Value in Health, Pharmacoeconomics, Health Economics and elsewhere, and we support manuscript preparation and submission.\n\nBuilding to CHEERS 2022 from the start is what makes this possible without a second build. It is also a discipline that improves the model."}},{"@type":"Question","name":"Which HTA agency do you build for?","acceptedAnswer":{"@type":"Answer","text":"Whichever you name — NICE, CADTH, ICER, HAS, IQWiG or another. They differ on perspective, discount rate, time horizon, acceptable comparator and how results are judged.\n\nName every target market at scoping. A model built for one and submitted to another is usually sent back, and reconfiguring afterwards costs more than specifying it at the start."}},{"@type":"Question","name":"What if the evidence does not support the case we want to make?","acceptedAnswer":{"@type":"Answer","text":"Then the report says so. That is uncomfortable and it is the entire value of an independent analysis — a model built towards a predetermined result does not survive review, and the reviewer is the person you least want to discover it.\n\nScoping quite often concludes that the study you need has not been run yet. Eighteen months before submission that is a plan; at submission it is a problem."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Data analytics","item":"https://pubrica.com/services/data-analytics-machine-learning/"},{"@type":"ListItem","position":3,"name":"Market access and HEOR","item":"https://pubrica.com/services/data-analytics-machine-learning/health-economics-outcome-research/"}]}];

